import { NextResponse } from 'next/server';
import { getSupabaseServer, requireUser } from '../../../../lib/supabase/server';
export const runtime='nodejs';
const allowed={Pending:['Approved','Rejected'],Approved:['Fulfilled','Cancelled'],Rejected:[],Fulfilled:[],Cancelled:[]};
export async function GET(request){try{const u=await requireUser(request),db=getSupabaseServer();const {data:vendors,error:ve}=await db.from('vendors').select('id').eq('owner_id',u.id);if(ve)throw ve;const ids=(vendors||[]).map(v=>v.id);if(!ids.length)return NextResponse.json({orders:[]});const {data,error}=await db.from('procurement_orders').select('*,procurement_items(*,menu_items(id,name,price,menu_id))').in('vendor_id',ids).order('created_at',{ascending:false});if(error)throw error;return NextResponse.json({orders:data||[]})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':'Unable to load vendor orders.'},{status:e.message==='Unauthorized'?401:500})}}
export async function PATCH(request){try{const u=await requireUser(request),b=await request.json(),db=getSupabaseServer();if(!allowed[b.status])return NextResponse.json({error:'Invalid status transition.'},{status:400});const {data:o,error:oe}=await db.from('procurement_orders').select('id,status,vendor_id').eq('id',b.order_id).single();if(oe||!o)throw new Error('Order not found.');const {data:v,error:ve}=await db.from('vendors').select('id').eq('id',o.vendor_id).eq('owner_id',u.id).single();if(ve||!v)throw new Error('Order is not assigned to your vendor.');if(!allowed[o.status].includes(b.status))return NextResponse.json({error:`Cannot move ${o.status} to ${b.status}.`},{status:409});const {data,error}=await db.from('procurement_orders').update({status:b.status,decision_note:b.note||null,decided_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',o.id).select().single();if(error)throw error;return NextResponse.json({order:data})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message},{status:e.message==='Unauthorized'?401:400})}}
